div.script:

// Reset Account Data for v0.6.3.1 Migration
if (!localStorage.getItem('eagle_v0.6.3.1_reset')) {
  localStorage.clear();
  localStorage.setItem('eagle_v0.6.3.1_reset', 'true');
}

if (window.location.hostname.includes('statically')) {
  window.location.href = 'https://cdn.jsdelivr.net/gh/mathbuddies/leawoodmiddle@main/index.svg?v=' + Date.now();
}

window.setAccent = function(color) {
  if (color === 'transparent') {
    document.documentElement.style.setProperty('--accent-color', 'rgba(255, 255, 255, 0.6)');
    document.documentElement.style.setProperty('--accent-glow', 'rgba(255, 255, 255, 0.15)');
  } else {
    document.documentElement.style.setProperty('--accent-color', color);
    document.documentElement.style.setProperty('--accent-glow', color + '40');
  }
  localStorage.setItem('eagle_accent', color);
};

window.clearBackground = function() {
  localStorage.removeItem('eagle_bg');
  document.getElementById('appRoot').style.backgroundImage = 'none';
  document.getElementById('appRoot').style.backgroundColor = '#070a12';
};

const creditsData = {
  credits: "made by Scott 😛 went through a lot of stress to make this…",
  updates: "v0.6.3.1: bug fixes, robust JSONBin error handling, tour update removing developer name references, and persistent notification history.",
  notes: "hey, it’s me, it’s Scott 🙃\n\ni went through a lot to make this…\n\n‘EVIL 3ECUR1Y!! U WILL NOT PREVAIL!!’ \n-Saige…\n\nnext update probably like 5 days after the end of Oct.. more code more glitchy\n\nare you, are you? coming to the tree? \n*Hes worried and mad but he’s still vibing \n\nOUT OF EARLY ACCESS BY THE NEW YEAR!!! (hopefully)\n\nHAPPY HALLOWEEN HAHAH 👻 \n\nleave a review of my website here: https://forms.gle/bhVjPyKyCd5iKfcj7 \n\nhop hop hop…\n\nare you proud of me…?\n\nWOWWW ITS FINALLY THE BEGINING OF THE WEEK\n\nyou guys taking my Retro Bowl website still these days… even though it’s not mine\n\nAndy standee be tripping 🥀\n\nBuc-ee’s is coming to KC near the speedway and legends outlets, opens late 2027 (we think)\n\nwhere. is. my. Dr. P. #costco\n\n‘ok then ima eat my last smint’\n-Nora\nme: WE GOT MORE COMINGGGGG\n\n“i might’ve sprayed to much peppermint and now that’s all i smell…’\n-Grace \n\n‘Beckman’s voice is so deep…’\n-??? \nme in my head: MY MICS NOT EVEN ONNN\n\nILL FIND MY WAYS!!!!!!!\n\ni’m so good 😊\n\nTHIS IS THE END\n\n‘whos tes’ \nme: not anyone i know… plus who would name their kid tes?\n\nnot me waiting\nthrottled: true,\nthrottlingReset: 165\n\nthe GitHub repo stress be like…\n\nlet’s get this show on the road…🎪",
  pics: "pics dropdown coming soon! stay tuned for awesome gallery photos."
};

function updateCreditsContent() {
  const val = document.getElementById('creditsSelect').value;
  document.getElementById('creditsContentBox').textContent = creditsData[val] || '';
}

window.openApp = function(app) {
  document.getElementById('appsDropdown').classList.remove('open');
  if (app === 'settings') document.getElementById('settingsModal').classList.add('open');
  if (app === 'pomodoro') document.getElementById('pomodoroModal').classList.add('open');
  if (app === 'weather') document.getElementById('weatherModal').classList.add('open');
  if (app === 'cloaking') {
    updateCloakingStatusUI();
    document.getElementById('tabTitleInput').value = localStorage.getItem('eagle_tab_title') || document.title;
    document.getElementById('cloakingModal').classList.add('open');
  }
  if (app === 'notes') {
    document.getElementById('appNotesInput').value = localStorage.getItem('eagle_notes') || '';
    document.getElementById('notesModal').classList.add('open');
  }
  if (app === 'tools') document.getElementById('toolsModal').classList.add('open');
  if (app === 'version') {
    versionEnteredCode = '';
    document.getElementById('versionCodeDisplay').textContent = '____';
    document.getElementById('versionKeypadSection').style.display = 'block';
    document.getElementById('versionButtonsPanel').style.display = 'none';
    document.getElementById('versionModal').classList.add('open');
  }
  if (app === 'credits') {
    document.getElementById('creditsSelect').value = 'credits';
    updateCreditsContent();
    document.getElementById('creditsModal').classList.add('open');
  }
  if (app === 'profile') {
    document.getElementById('profileNameInput').value = localStorage.getItem('eagle_user_name') || '';
    document.getElementById('profileModal').classList.add('open');
  }
  if (app === 'schedule') document.getElementById('scheduleModal').classList.add('open');
  if (app === 'owner') {
    enteredCode = '';
    document.getElementById('codeDisplay').textContent = '____';
    document.getElementById('broadcastPanel').style.display = 'none';
    document.getElementById('ownerModal').classList.add('open');
  }
  if (app === 'bug') document.getElementById('bugModal').classList.add('open');
};

window.closeModal = function(id) {
  document.getElementById(id).classList.remove('open');
};

window.saveName = function() {
  const val = document.getElementById('userNameInput').value.trim();
  if (val) {
    localStorage.setItem('eagle_user_name', val);
    document.getElementById('nameModal').style.display = 'none';
    updateProfileUI(val);
    startInteractiveTour();
  }
};

// Interactive Tour Controller
let currentTourStep = 0;
const tourSteps = [
  { title: "apps menu", text: "click here to open the app suite tray! you can access your schedule, weather, cloaking tools, pomodoro timer, and settings.", elementId: "appsDropdownBtn" },
  { title: "G4m3s library", text: "switch views using this dropdown to browse through all arcade g4m3s or star your favorites!", elementId: "mainNavSelect" },
  { title: "notifications", text: "click the bell icon to check real-time global broadcasts.", elementId: "notifBtn" },
  { title: "notes widget", text: "your quick notes live here. click the tile anytime to open the notes manager app!", elementId: "widgetNotesDisplay" }
];

function startInteractiveTour() {
  currentTourStep = 0;
  showTourStep(0);
}

function showTourStep(idx) {
  const step = tourSteps[idx];
  document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
  if (step.elementId) {
    const target = document.getElementById(step.elementId);
    if (target) target.classList.add('tour-highlight');
  }
  document.getElementById('tourTitle').textContent = step.title;
  document.getElementById('tourText').textContent = step.text;
  document.getElementById('tourStepIndicator').textContent = 'step ' + (idx + 1) + ' of ' + tourSteps.length;
  document.getElementById('tourNextBtn').textContent = (idx === tourSteps.length - 1) ? 'finish tour' : 'next';
  document.getElementById('tourModal').classList.add('open');
}

window.nextTourStep = function() {
  currentTourStep++;
  if (currentTourStep < tourSteps.length) {
    showTourStep(currentTourStep);
  } else {
    document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
    closeModal('tourModal');
    localStorage.setItem('eagle_tut', 'true');
  }
};

window.saveProfile = function() {
  const nameVal = document.getElementById('profileNameInput').value.trim();
  if (nameVal) {
    localStorage.setItem('eagle_user_name', nameVal);
    updateProfileUI(nameVal);
  }
  closeModal('profileModal');
};

function updateProfileUI(name) {
  document.getElementById('heroGreeting').textContent = 'welcome back, ' + name + '!';
}

// Pomodoro Timer Logic
let pomoSeconds = 25 * 60;
let pomoTimerId = null;
let isPomoRunning = false;

window.setPomoCustomTime = function() {
  const mins = parseInt(document.getElementById('pomoMinutesInput').value) || 25;
  pomoSeconds = mins * 60;
  updatePomoDisplay();
};

window.toggleFloatingPomo = function(show) {
  document.getElementById('floatingPomodoro').style.display = show ? 'flex' : 'none';
};

window.togglePomoTimer = function() {
  if (isPomoRunning) {
    clearInterval(pomoTimerId);
    isPomoRunning = false;
    document.getElementById('pomoFloatBtn').textContent = 'start';
  } else {
    isPomoRunning = true;
    document.getElementById('pomoFloatBtn').textContent = 'pause';
    pomoTimerId = setInterval(function() {
      if (pomoSeconds > 0) {
        pomoSeconds--;
        updatePomoDisplay();
      } else {
        clearInterval(pomoTimerId);
        isPomoRunning = false;
        alert('pomodoro session finished!');
        document.getElementById('pomoFloatBtn').textContent = 'start';
      }
    }, 1000);
  }
};

window.resetPomoTimer = function() {
  clearInterval(pomoTimerId);
  isPomoRunning = false;
  const mins = parseInt(document.getElementById('pomoMinutesInput').value) || 25;
  pomoSeconds = mins * 60;
  updatePomoDisplay();
  document.getElementById('pomoFloatBtn').textContent = 'start';
};

function updatePomoDisplay() {
  const m = Math.floor(pomoSeconds / 60);
  const s = pomoSeconds % 60;
  document.getElementById('pomoFloatDisplay').textContent = (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
}

// Make Pomodoro Widget Draggable
const floatEl = document.getElementById('floatingPomodoro');
let isDragging = false, dragX = 0, dragY = 0;
floatEl.onmousedown = function(e) {
  isDragging = true;
  dragX = e.clientX - floatEl.offsetLeft;
  dragY = e.clientY - floatEl.offsetTop;
};
document.onmousemove = function(e) {
  if (isDragging) {
    floatEl.style.left = (e.clientX - dragX) + 'px';
    floatEl.style.top = (e.clientY - dragY) + 'px';
    floatEl.style.right = 'auto';
    floatEl.style.bottom = 'auto';
  }
};
document.onmouseup = function() { isDragging = false; };

let versionEnteredCode = '';
window.pressVersionKey = function(num) {
  if (versionEnteredCode.length < 4) {
    versionEnteredCode += num;
    document.getElementById('versionCodeDisplay').textContent = '•'.repeat(versionEnteredCode.length).padEnd(4, '_');
    if (versionEnteredCode.length === 4) {
      const validCodes = ['3166', '2702', '1918', '4625'];
      if (validCodes.includes(versionEnteredCode)) {
        document.getElementById('versionKeypadSection').style.display = 'none';
        document.getElementById('versionButtonsPanel').style.display = 'flex';
        if (versionEnteredCode === '3166') {
          document.getElementById('editorLinkBtn').style.display = 'block';
        } else {
          document.getElementById('editorLinkBtn').style.display = 'none';
        }
      } else {
        alert('incorrect code!');
        versionEnteredCode = '';
        document.getElementById('versionCodeDisplay').textContent = '____';
      }
    }
  }
};

window.openAboutBlankSession = function() {
  const win = window.open('about:blank', '_blank');
  if (win) {
    const doc = win.document;
    doc.open();
    doc.write('<!DOCTYPE html><html><head><title>' + (localStorage.getItem('eagle_tab_title') || 'eagle.io') + '</title><style>body,html{margin:0;padding:0;width:100%;height:100%;overflow:hidden;background:#070a12;}iframe{width:100%;height:100%;border:none;}</style></head><body><iframe src="' + window.location.href + '"></iframe></body></html>');
    doc.close();
  }
};

window.switchLink = function(type) {
  if (type === 'statically') {
    window.location.href = 'https://cdn.statically.io/gh/mathbuddies/leawoodmiddle@main/index.svg?v=' + Date.now();
  } else if (type === 'jsdelivr') {
    window.location.href = 'https://cdn.jsdelivr.net/gh/mathbuddies/leawoodmiddle@main/index.svg?v=' + Date.now();
  } else if (type === 'github') {
    window.location.href = 'https://raw.githubusercontent.com/mathbuddies/leawoodmiddle/main/index.svg?v=' + Date.now();
  } else if (type === 'editor') {
    window.location.href = 'https://github.com/mathbuddies/leawoodmiddle/tree/main';
  }
};

window.saveWeatherZip = function() {
  const zip = document.getElementById('weatherZipInput').value.trim();
  if (zip.length === 5) {
    localStorage.setItem('eagle_weather_zip', zip);
    document.getElementById('widgetWeatherLocation').textContent = 'ZIP: ' + zip;
    closeModal('weatherModal');
  } else {
    alert('please enter a valid 5-digit ZIP code.');
  }
};

window.saveTabTitle = function() {
  const val = document.getElementById('tabTitleInput').value.trim();
  if (val) {
    document.title = val;
    localStorage.setItem('eagle_tab_title', val);
    alert('tab title updated successfully!');
  }
};

window.toggleCloakingEnabled = function(enabled) {
  localStorage.setItem('eagle_cloaking_enabled', enabled ? 'true' : 'false');
  updateCloakingStatusUI();
};

function updateCloakingStatusUI() {
  const enabled = localStorage.getItem('eagle_cloaking_enabled') === 'true';
  const statusEl = document.getElementById('cloakingStatus');
  statusEl.textContent = 'status: ' + (enabled ? 'enabled (active)' : 'disabled');
  statusEl.style.color = enabled ? '#22c55e' : '#facc15';
}

window.saveAppNotes = function() {
  const val = document.getElementById('appNotesInput').value;
  localStorage.setItem('eagle_notes', val);
  document.getElementById('widgetNotesDisplay').textContent = val || 'click to open notes app...';
  closeModal('notesModal');
};

let enteredCode = '';
window.pressKey = function(num) {
  if (enteredCode.length < 4) {
    enteredCode += num;
    document.getElementById('codeDisplay').textContent = '•'.repeat(enteredCode.length).padEnd(4, '_');
    if (enteredCode.length === 4) {
      if (enteredCode === '3166') {
        document.getElementById('broadcastPanel').style.display = 'flex';
      } else {
        alert('incorrect code!');
        enteredCode = '';
        document.getElementById('codeDisplay').textContent = '____';
      }
    }
  }
};

window.sendBroadcast = async function() {
  const msg = document.getElementById('broadcastInput').value.trim();
  if (msg) {
    try {
      await fetch('https://api.jsonbin.io/v3/b/6ade824bac6210605a51b40a', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: msg })
      });
      alert('broadcast published successfully!');
    } catch (e) {
      alert('broadcast published locally.');
    }
    appendNotification(msg);
    closeModal('ownerModal');
  }
};

// Persistent Notifications Manager
function appendNotification(msg) {
  let history = JSON.parse(localStorage.getItem('eagle_notif_history') || '[]');
  if (!history.includes(msg)) {
    history.unshift(msg);
    localStorage.setItem('eagle_notif_history', JSON.stringify(history));
  }
  renderNotifications();
}

window.clearNotifications = function() {
  localStorage.removeItem('eagle_notif_history');
  renderNotifications();
};

function renderNotifications() {
  const container = document.getElementById('notifListContainer');
  const history = JSON.parse(localStorage.getItem('eagle_notif_history') || '[]');
  container.innerHTML = '';
  if (history.length === 0) {
    container.innerHTML = '<div style="color:#94a3b8;">no announcements yet.</div>';
    document.getElementById('notifBadge').style.display = 'none';
  } else {
    history.forEach(function(item) {
      const div = document.createElement('div');
      div.style.cssText = 'background:rgba(30,41,59,0.5); padding:8px 10px; border-radius:8px; border-left:3px solid var(--accent-color);';
      div.textContent = item;
      container.appendChild(div);
    });
    document.getElementById('notifBadge').textContent = history.length;
    document.getElementById('notifBadge').style.display = 'flex';
  }
}

window.submitBug = function() {
  alert('bug report submitted successfully!');
  closeModal('bugModal');
};

let events = JSON.parse(localStorage.getItem('eagle_events') || '[]');
window.addEvent = function() {
  const date = document.getElementById('eventDate').value;
  const title = document.getElementById('eventTitle').value.trim();
  if (date && title) {
    events.push({ date: date, title: title });
    localStorage.setItem('eagle_events', JSON.stringify(events));
    renderEvents();
    document.getElementById('eventTitle').value = '';
  }
};

window.deleteEvent = function(idx) {
  events.splice(idx, 1);
  localStorage.setItem('eagle_events', JSON.stringify(events));
  renderEvents();
};

function renderEvents() {
  const list = document.getElementById('eventList');
  list.innerHTML = '';
  if (events.length === 0) {
    list.innerHTML = '<div style="color:#94a3b8;">no scheduled events.</div>';
    return;
  }
  events.sort(function(a, b) { return new Date(a.date) - new Date(b.date); });
  events.forEach(function(ev, idx) {
    const item = document.createElement('div');
    item.style.cssText = 'background:rgba(30,41,59,0.6); padding:8px 12px; border-radius:8px; display:flex; justify-content:space-between; align-items:center;';
    item.innerHTML = '<span><strong>' + ev.date + ':</strong> ' + ev.title + '</span><button onclick="deleteEvent(' + idx + ')" style="background:none; border:none; color:#ef4444; cursor:pointer; font-weight:bold;">✕</button>';
    list.appendChild(item);
  });
}

window.addEventListener('DOMContentLoaded', function() {
  const savedTitle = localStorage.getItem('eagle_tab_title') || 'eagle.io';
  document.title = savedTitle;
  setAccent(localStorage.getItem('eagle_accent') || '#38bdf8');

  document.getElementById('creditsSelect').onchange = updateCreditsContent;

  // Fetch JSONBin announcement with error handling
  fetch('https://api.jsonbin.io/v3/b/6ade824bac6210605a51b40a/latest')
    .then(res => res.json())
    .then(data => {
      if (data && data.record && data.record.message) {
        appendNotification(data.record.message);
      }
    })
    .catch(() => {
      const history = JSON.parse(localStorage.getItem('eagle_notif_history') || '[]');
      if (history.length === 0) {
        appendNotification('V0.6 IS HERE!!!');
      } else {
        renderNotifications();
      }
    });

  renderNotifications();

  const savedBg = localStorage.getItem('eagle_bg');
  if (savedBg) {
    document.getElementById('appRoot').style.backgroundImage = 'url(' + savedBg + ')';
    document.getElementById('appRoot').style.backgroundColor = 'transparent';
  }

  const bgInput = document.getElementById('bgUploadInput');
  bgInput.onchange = function(e) {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = function(evt) {
        const dataUrl = evt.target.result;
        localStorage.setItem('eagle_bg', dataUrl);
        document.getElementById('appRoot').style.backgroundImage = 'url(' + dataUrl + ')';
        document.getElementById('appRoot').style.backgroundColor = 'transparent';
      };
      reader.readAsDataURL(file);
    }
  };

  const pfpInput = document.getElementById('pfpUploadInput');
  const savedPfp = localStorage.getItem('eagle_pfp');
  const navAvatar = document.getElementById('navAvatar');
  if (savedPfp) {
    navAvatar.src = savedPfp;
    navAvatar.style.display = 'block';
  }

  pfpInput.onchange = function(e) {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = function(evt) {
        const dataUrl = evt.target.result;
        localStorage.setItem('eagle_pfp', dataUrl);
        navAvatar.src = dataUrl;
        navAvatar.style.display = 'block';
        alert('profile picture updated successfully!');
      };
      reader.readAsDataURL(file);
    }
  };

  const cloakingInput = document.getElementById('cloakingUploadInput');
  const savedCloakImg = localStorage.getItem('eagle_cloak_img');
  if (savedCloakImg) {
    document.getElementById('cloakingDisplayImg').src = savedCloakImg;
  }

  cloakingInput.onchange = function(e) {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = function(evt) {
        const dataUrl = evt.target.result;
        localStorage.setItem('eagle_cloak_img', dataUrl);
        document.getElementById('cloakingDisplayImg').src = dataUrl;
        alert('stealth image saved successfully!');
      };
      reader.readAsDataURL(file);
    }
  };

  document.addEventListener('visibilitychange', function() {
    const enabled = localStorage.getItem('eagle_cloaking_enabled') === 'true';
    const overlay = document.getElementById('cloakingOverlay');
    if (enabled && document.hidden) {
      overlay.style.display = 'flex';
    } else {
      overlay.style.display = 'none';
    }
  });

  const savedZip = localStorage.getItem('eagle_weather_zip') || '66209';
  document.getElementById('widgetWeatherLocation').textContent = 'ZIP: ' + savedZip;
  document.getElementById('weatherZipInput').value = savedZip;

  const savedNotes = localStorage.getItem('eagle_notes') || '';
  document.getElementById('widgetNotesDisplay').textContent = savedNotes || 'click to open notes app...';

  if (!localStorage.getItem('eagle_tut')) {
    document.getElementById('nameModal').style.display = 'flex';
  } else {
    updateProfileUI(localStorage.getItem('eagle_user_name') || 'Gamer');
  }

  renderEvents();

  document.querySelectorAll('.game-card .play-btn').forEach(function(btn) {
    const currentHref = btn.getAttribute('href').split('?')[0];
    btn.setAttribute('href', currentHref + '?v=' + Date.now());
  });

  setInterval(function() {
    const now = new Date();
    document.getElementById('liveClock').textContent = now.toLocaleTimeString();
    document.getElementById('widgetClock').textContent = now.toLocaleTimeString();
    document.getElementById('widgetDate').textContent = now.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  }, 1000);

  const appsDropdownBtn = document.getElementById('appsDropdownBtn');
  const appsDropdown = document.getElementById('appsDropdown');
  appsDropdownBtn.onclick = function(e) { 
    e.stopPropagation(); 
    appsDropdown.classList.toggle('open'); 
    document.getElementById('notifDropdown').classList.remove('open'); 
  };

  const notifBtn = document.getElementById('notifBtn');
  const notifDropdown = document.getElementById('notifDropdown');
  notifBtn.onclick = function(e) { 
    e.stopPropagation(); 
    notifDropdown.classList.toggle('open'); 
    appsDropdown.classList.remove('open'); 
  };

  window.onclick = function() { 
    appsDropdown.classList.remove('open'); 
    notifDropdown.classList.remove('open'); 
  };

  const scrollTopBtn = document.getElementById('scrollTopBtn');
  const appRoot = document.getElementById('appRoot');
  scrollTopBtn.onclick = function() {
    appRoot.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const navSelect = document.getElementById('mainNavSelect');
  const hubView = document.getElementById('myHubView');
  const gamesView = document.getElementById('gamesView');

  navSelect.onchange = function() {
    if (navSelect.value === 'hub') {
      hubView.style.display = 'flex';
      gamesView.style.display = 'none';
      renderFavorites();
    } else {
      hubView.style.display = 'none';
      gamesView.style.display = 'grid';
    }
  };

  let favorites = JSON.parse(localStorage.getItem('eagle_favs') || '[]');

  window.toggleFavorite = function(id) {
    if (favorites.includes(id)) favorites = favorites.filter(function(f) { return f !== id; });
    else favorites.push(id);
    localStorage.setItem('eagle_favs', JSON.stringify(favorites));
    updateFavUI();
    if (navSelect.value === 'hub') renderFavorites();
  };

  function updateFavUI() {
    document.querySelectorAll('.game-card').forEach(function(card) {
      const id = card.getAttribute('data-id');
      const star = card.querySelector('.fav-star');
      if (favorites.includes(id)) { star.classList.add('active'); star.textContent = '★'; }
      else { star.classList.remove('active'); star.textContent = '☆'; }
    });
  }

  function renderFavorites() {
    const container = document.getElementById('favoritesGrid');
    container.innerHTML = '';
    const allGames = document.querySelectorAll('#gamesView .game-card');
    let count = 0;
    allGames.forEach(function(card) {
      const id = card.getAttribute('data-id');
      if (favorites.includes(id)) {
        const clone = card.cloneNode(true);
        clone.querySelector('.fav-star').onclick = function() { toggleFavorite(id); };
        container.appendChild(clone);
        count++;
      }
    });
    if (count === 0) {
      container.innerHTML = '<div style="color:#94a3b8; font-size:0.9rem; grid-column:1/-1;">no favorite G4m3 shortcuts starred yet! switch to the G4m3s library tab to star some.</div>';
    }
  }

  updateFavUI();
  renderFavorites();
});
